<template>
  <main class="min-h-screen bg-[#0d0e12] px-4 py-6 text-zinc-100 sm:px-6"><div class="mx-auto max-w-5xl"><RouterLink to="/" class="text-sm text-amber-300">← 返回工作台</RouterLink><div class="mt-6"><p class="text-[10px] uppercase tracking-[0.18em] text-amber-500">BATCH SHARE</p><h1 class="mt-1 text-2xl font-semibold">搬货加价 / 群发整理</h1><p class="mt-2 text-sm text-zinc-400">把供应商发来的散乱商品信息整理成统一报价文案，复制到多个群即可。</p></div><div class="mt-6 grid gap-5 lg:grid-cols-[minmax(0,1fr)_minmax(0,1fr)]"><section class="border border-zinc-800 bg-[#141519] p-4 sm:p-5"><label class="block text-xs text-zinc-400">统一加价（元）<input v-model.number="markup" type="number" step="0.01" class="field" placeholder="例如 30" /></label><label class="mt-4 block text-xs text-zinc-400">供应商原始信息<textarea v-model="rawText" rows="13" class="field resize-y" placeholder="每行一款，例如：\n古法手镯 祥云 20.5g  ¥14500\n足金吊坠 福牌 5g  ¥3800"></textarea></label><div class="mt-3 flex gap-2"><button class="bg-amber-400 px-4 py-2.5 text-sm font-semibold text-zinc-950" @click="parseItems">生成群发报价</button><button class="border border-zinc-700 px-4 py-2.5 text-sm text-zinc-300" @click="rawText = ''; items = []">清空</button></div><p class="mt-3 text-[11px] leading-5 text-zinc-500">工具只在本机处理文本，不会自动抓取或发送到群。发送前请自行核对供应商价格、库存和授权。</p></section><section class="border border-amber-500/25 bg-[#171611] p-4 sm:p-5"><div class="flex items-center justify-between"><h2 class="text-sm font-semibold text-amber-100">待发送内容</h2><button v-if="output" class="text-xs text-amber-300" @click="copyOutput">复制全部</button></div><textarea v-model="output" rows="16" class="mt-3 w-full resize-y border border-zinc-700 bg-[#0d0e12] p-3 text-sm leading-6 text-zinc-200 outline-none focus:border-amber-400/60" placeholder="生成后会显示统一格式的群发文本"></textarea><p v-if="feedback" class="mt-2 text-xs text-emerald-300">{{ feedback }}</p></section></div></div></main>
</template>
<script setup>
import { ref } from 'vue';
const rawText = ref(''); const markup = ref(30); const output = ref(''); const feedback = ref(''); const items = ref([]);
function parseLine(line) { const clean = line.replace(/\s+/g, ' ').trim(); if (!clean) return null; const priceMatch = clean.match(/[¥￥]?\s*(\d+(?:\.\d+)?)(?:元)?\s*$/); const price = priceMatch ? Number(priceMatch[1]) : 0; const title = priceMatch ? clean.slice(0, priceMatch.index).trim() : clean; return { title, price, sell: price ? price + Number(markup.value || 0) : 0 }; }
function parseItems() { items.value = rawText.value.split(/\n+/).map(parseLine).filter(Boolean); output.value = items.value.map((item, index) => `${index + 1}. ${item.title}${item.sell ? `｜档口报价 ¥${item.sell.toFixed(2)}` : '｜价格私聊'}\n现货可问，支持视频看货，喜欢直接留款号。`).join('\n\n'); feedback.value = items.value.length ? `已整理 ${items.value.length} 款，发送前请复核价格。` : '请输入至少一行商品信息。'; }
async function copyOutput() { try { await navigator.clipboard.writeText(output.value); feedback.value = '已复制，可粘贴到微信群或朋友圈。'; } catch { feedback.value = '复制失败，请手动复制文本。'; } }
</script>
<style scoped>.field{margin-top:.375rem;width:100%;border:1px solid rgb(63 63 70);background:#0d0e12;padding:.625rem .75rem;color:#f4f4f5;outline:none}.field:focus{border-color:rgb(251 191 36 / .6)}</style>
